const svg=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.layers}</svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const compact=n=>n==null?'—':new Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(n);
const exact=n=>n==null?'Unavailable':new Intl.NumberFormat('en').format(n);
const date=value=>value?new Intl.DateTimeFormat('en',{month:'short',day:'numeric',year:'numeric'}).format(new Date(value)):'Unavailable';
const gh=p=>`https://github.com/${p.repo}`;
const appLink=p=>`#/app/${p.id}`;
const externalAttrs='target="_blank" rel="noopener noreferrer"';
let projects=[...catalog,...openCatalog,...trendingCatalog],snapshot={},trendSnapshot={},assetSources={},officialIcons={},reviewSnapshot={};
let communitySubmissions=[],wantedRequests=[],catalogChoiceList=[],currentUser=null,adminQueue=null,adminLoading=false,adminError='';
let communityError='',wantedError='',adminFilter='all';
let visibleLimit=24,lastResultKey='';
let toastTimer;
let saved;
try {saved=new Set(JSON.parse(localStorage.getItem('openstore-saved')||'[]'));} catch {saved=new Set();}
function icon(p){
 const asset=officialIcons[p.id];
 const src=p.iconUrl||asset?.file&&`assets/${asset.file}`;
 return `<span class="app-icon image-icon" title="Project icon">${src?`<img src="${esc(src)}" alt="" loading="lazy" width="53" height="53">`:svg(p.icon||'layers')}</span>`;
}
function rating(p){const r=p.review;return r?`<a class="review-rating" href="${esc(r.url)}" ${externalAttrs} title="${esc(r.provider)} user rating, captured ${date(r.capturedAt)}">${svg('star')}<strong>${r.rating.toFixed(1)}</strong><span>${exact(r.count)} reviews · ${esc(r.provider)}</span></a>`:'';}
function reviewCard(p){if(!p.review)return row(p);return `<article class="review-card"><a class="review-app" href="${appLink(p)}">${icon(p)}<div><h3>${esc(p.name)}</h3><p>${esc(p.bestFor||p.review.useCase)}</p></div>${svg('chevron')}</a>${rating(p)}<p class="review-summary">${esc(p.review.summary)}</p>${p.review.feedbackUrl?`<a class="text-link feedback-source" href="${esc(p.review.feedbackUrl)}" ${externalAttrs}>Feedback notes · ${esc(p.review.feedbackProvider)} ${svg('external')}</a>`:''}<div class="review-card-foot"><span>${svg('star')}${compact(p.stars)} GitHub stars</span><a href="${appLink(p)}" class="text-link">Explore app ${svg('chevron')}</a></div></article>`;}
function evidence(p){return `<section class="selection-panel"><div class="selection-title"><span class="eyebrow">Best for</span><h2>A good fit for ${esc((p.bestFor||p.description.replace(/\.$/,''))[0].toLowerCase()+(p.bestFor||p.description.replace(/\.$/,'')).slice(1))}.</h2></div>${p.consideration?`<p class="fit-consideration">${esc(p.consideration)}</p>`:''}<div class="feedback-panel"><div><h3>User feedback</h3>${p.review?rating(p):'<span class="unrated">No aggregate rating verified</span>'}</div><p>${p.review?esc(p.review.summary):'Explore discussions, issues, and documentation to see how this project fits your workflow.'}</p><div class="feedback-links">${p.review?`<a class="text-link" href="${esc(p.review.url)}" ${externalAttrs}>Read reviews ${svg('external')}</a><span>${p.review.smallSample?'Small sample · ':''}Captured ${date(p.review.capturedAt)}</span>`:`<a class="text-link" href="${gh(p)}/discussions" ${externalAttrs}>Community discussions ${svg('external')}</a>`}${p.review?.feedbackUrl?`<a class="text-link" href="${esc(p.review.feedbackUrl)}" ${externalAttrs}>Feedback notes · ${esc(p.review.feedbackProvider)} ${svg('external')}</a>`:''}<a class="text-link" href="${gh(p)}/issues" ${externalAttrs}>Project issues ${svg('external')}</a></div><p class="review-context">${p.review?'Product-level ratings can include hosted and paid editions. ':''}GitHub stars measure repository interest, not customer satisfaction.</p></div></section>`;}
function sourceBadge(p){return p.sourceAvailable?'<span class="source-badge">Source-available</span>':'';}
function row(p){return `<article class="app-row"><a href="${appLink(p)}" aria-label="Explore ${esc(p.name)}">${icon(p)}</a><div class="app-copy"><h3><a href="${appLink(p)}">${esc(p.name)}</a>${sourceBadge(p)}</h3><p>${esc(p.description)}</p><div class="replace-label">Alternative to <b>${esc(p.replaces[0])}</b></div><div class="app-meta"><span class="stars" title="${exact(p.stars)} GitHub stars as of ${date(snapshot.fetchedAt)}">${svg('star')}${compact(p.stars)}</span><span class="divider">·</span><a href="#/browse?category=${encodeURIComponent(p.category)}">${esc(p.category)}</a><span class="divider">·</span><span class="platform">${p.platforms.includes('Web')?'Web':p.platforms[0]}</span>${p.weeklyStars?`<span class="trend-badge" title="GitHub weekly stars as of ${date(trendSnapshot.fetchedAt)}">↗ ${compact(p.weeklyStars)} this week</span>`:''}</div></div><a class="app-github" href="${gh(p)}" ${externalAttrs} aria-label="${esc(p.name)} on GitHub">${svg('github')}</a></article>`;}
function card(p){return `<article class="catalog-card"><div class="catalog-card-top"><a href="${appLink(p)}" aria-label="Explore ${esc(p.name)}">${icon(p)}</a><div class="catalog-identity"><h3><a href="${appLink(p)}">${esc(p.name)}</a></h3><p>${esc(p.category)}</p></div><a class="app-github" href="${gh(p)}" ${externalAttrs} aria-label="${esc(p.name)} on GitHub">${svg('github')}</a></div><p class="catalog-description" title="${esc(p.description)}">${esc(p.description)}</p><div class="replacement-chip"><span>Alternative to</span><b>${esc(p.replaces[0])}</b></div><div class="card-fit"><span>Best for</span><p title="${esc(p.bestFor)}">${esc(p.bestFor)}</p></div><div class="card-evidence"><span class="github-stat" title="${exact(p.stars)} GitHub stars">${svg('github')}<strong>${compact(p.stars)}</strong><span>GitHub stars</span>${p.weeklyStars?`<span class="trend-badge">↗ ${compact(p.weeklyStars)} / week</span>`:''}</span>${rating(p)}</div><div class="card-platforms">${svg('globe')}<span>${esc(p.platforms.join(' · '))}</span></div><div class="catalog-card-bottom"><div class="card-badges">${p.selfHosted?'<span class="selfhost-tag">Self-hosted</span>':''}${sourceBadge(p)}</div><a href="${appLink(p)}" class="card-action">View app ${svg('arrow')}</a></div></article>`;}

function leaderboard(list){const max=Math.max(1,...list.map(p=>p.weeklyStars||0));return `<div class="leaderboard"><div class="leaderboard-head" aria-hidden="true"><span>#</span><span>Project</span><span>Category</span><span>This week</span><span>Stars</span><span></span></div><ol>${list.map((p,i)=>`<li class="leaderboard-row"><span class="leaderboard-rank">${i+1}</span><a class="leaderboard-app" href="${appLink(p)}">${icon(p)}<span><strong>${esc(p.name)}</strong><small>${esc(p.repo)}</small></span></a><span class="leaderboard-category">${esc(p.category)}</span><span class="leaderboard-trend" title="${exact(p.weeklyStars)} GitHub stars this week as of ${date(trendSnapshot.fetchedAt)}"><span class="leaderboard-bar" aria-hidden="true"><span style="width:${Math.max(4,Math.round((p.weeklyStars||0)/max*100))}%"></span></span><span class="leaderboard-value">+${compact(p.weeklyStars)}</span></span><span class="leaderboard-stars" title="${exact(p.stars)} GitHub stars">${compact(p.stars)}</span><a class="app-github" href="${gh(p)}" ${externalAttrs} aria-label="${esc(p.name)} on GitHub">${svg('github')}</a></li>`).join('')}</ol></div>`;}
function heading(title,subtitle,link,label='See all',glyph=''){return `<div class="section-heading"><div><h2>${glyph?svg(glyph):''}${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${link?`<a class="text-link" href="${link}">${label} ${svg('chevron')}</a>`:''}</div>`;}
function searchBox(query=''){return `<div class="search-box">${svg('search')}<input type="search" id="app-search" aria-label="Search open-source alternatives" placeholder="Search open-source alternatives…" autocomplete="off" value="${esc(query)}">${query?'<button class="search-clear" data-action="clear-search" aria-label="Clear search">×</button>':'<kbd>⌘ K</kbd>'}</div>`;}
function categoryCard(c,directory=false){const count=projects.filter(p=>p.category===c.name).length;return `<a class="category-card" href="#/browse?category=${encodeURIComponent(c.name)}" style="--category-color:${c.color}">${svg(c.icon)}<div><span>${esc(c.name)}</span>${directory?`<p>${count} curated ${count===1?'app':'apps'} ${count?'→':''}</p>`:''}</div></a>`;}
function featureArtwork(style){const file=style==='cut'?'video':style;return `<div class="promo-visual" aria-hidden="true"><img src="assets/promo-${file}.svg" alt="" width="400" height="240"></div>`;}
function discoveryHero(){
 return `<section class="intro hero-intro discovery-hero" aria-labelledby="discovery-title">
 <div class="hero-heading"><div class="hero-label"><span class="eyebrow">The open-source app store</span><span class="hero-label-divider" aria-hidden="true"></span><span class="hero-count">${projects.length} reviewed projects</span></div>
 <h1 id="discovery-title">Find the best open-source alternative.</h1>
 <p>Curated alternatives to the software you already use.</p>
 <div class="hero-search-area">${searchBox()}</div>
 <nav class="hero-categories" aria-label="Discover apps by category"><a href="#/browse">All apps</a>${['AI','Developer Tools','Design','Productivity','Video','Privacy'].map(name=>`<a href="#/browse?category=${encodeURIComponent(name)}">${esc(name)}</a>`).join('')}<a href="#/categories">More…</a></nav></div>
 <div class="popular-searches"><span>Popular:</span><div class="replacement-suggestions">${['Photoshop','Notion','CapCut','ChatGPT'].map(name=>`<button data-search="${name}">${name}</button>`).join('')}</div></div>
 </section>`;
}
function home(){const find=id=>projects.find(p=>p.id===id);const code=find('opencode'),cut=find('opencut'),pen=find('penpot');const trending=projects.filter(p=>p.trending).sort((a,b)=>b.weeklyStars-a.weeklyStars).slice(0,6);return `
${discoveryHero()}

<section class="section">${heading('Editor’s picks','Three standouts to start with.','#/browse','All apps')}<div class="feature-grid">
${[[code,'code','Coding','Your next coding companion.','Meet OpenCode. Make something great.'],[cut,'cut','Video','Your story. Your editor.','Create without the subscription.'],[pen,'design','Design','Good design. Open by design.','A canvas for your next idea.']].map(([p,style,label,title,tagline])=>`<a class="feature feature-${style}" href="${appLink(p)}"><div class="feature-art"><span class="eyebrow">${label}</span><h3>${title}</h3><p class="feature-tagline">${tagline}</p>${featureArtwork(style)}</div><div class="feature-foot">${icon(p)}<div><h4>${esc(p.name)}</h4><p>Alternative to ${esc(p.replaces[0])}</p></div>${svg('arrow','feature-arrow')}</div></a>`).join('')}
</div></section>
<section class="section open-family-section">${heading('The Open family','Projects that carry “Open” in their name.','#/browse?openOnly=1',`All ${projects.filter(p=>p.name.toLowerCase().startsWith('open')).length}`)}<div class="apps-grid">${['open-notebook','openpencil','openwhispr','opencloud','opensign','opendesign'].map(id=>row(find(id))).join('')}</div></section>
<section class="section">${heading('Trending this week','Catalog projects on GitHub’s weekly Trending page.','#/trending','See all')}${leaderboard(trending)}<p class="trend-note">${svg('info')} From GitHub’s weekly Trending page · Snapshot ${date(trendSnapshot.fetchedAt)}</p></section>
<section class="section categories-section">${heading('Categories','','#/categories','All categories')}<div class="category-grid">${categories.slice(0,9).map(c=>categoryCard(c)).join('')}</div></section>
<section class="section">${heading('Popular','Most-starred projects in the collection.','#/browse?sort=stars','See all')}<div class="recent-grid">${['appflowy','actual','openobserve'].map(id=>{const p=find(id);return `<article class="recent-card"><a class="recent-cover" href="${appLink(p)}"><img src="assets/${p.screens[0][0]}" alt="${esc(p.screens[0][1])}" loading="lazy" width="500" height="280"></a>${row(p)}</article>`;}).join('')}</div></section>
<section class="section reader-section">${heading('Well reviewed','Established apps with published user ratings.','#/browse?reviewed=1&sort=reviews','See all')}<div class="review-grid">${['openproject','openshot','opencart'].map(id=>reviewCard(find(id))).join('')}</div><p class="review-collection-note">Published ratings and review counts from Capterra · ${date(reviewSnapshot.fetchedAt)} · Ratings cover each listed product, including its hosted or paid editions.</p></section>
<section class="community-entry"><div><span class="eyebrow">Community</span><h2>Know a project that belongs here?</h2><p>Recommend promising finds while OpenStore’s editorial review keeps the primary catalog carefully curated.</p></div><div class="community-entry-actions"><a class="button button-primary" href="#/submit">Submit an app</a><a class="button button-secondary" href="#/community">Community Finds</a><a class="button button-secondary" href="#/wanted">Wanted</a></div></section>
<section class="collection-banner">
  <div class="collection-copy">
    <span class="eyebrow">Collection</span>
    <h2>An open workspace</h2>
    <p>Notes, projects, whiteboards, and infrastructure—an independent toolkit for work that stays in your hands.</p>
    <a class="collection-action" href="#/browse?category=Productivity">Explore productivity ${svg('arrow')}</a>
  </div>
  <div class="collection-panel">
    
    <div class="collection-apps">${[['appflowy','Notes & docs'],['openproject','Projects & teams'],['openboard','Ideas & planning'],['opentofu','Infrastructure']].map(([id,role],i)=>{const p=find(id);return `<a class="collection-app" href="${appLink(p)}">${icon(p)}<span class="collection-app-copy"><strong>${esc(p.name)}</strong><small>${role}</small></span>${svg('arrow','collection-app-arrow')}</a>`;}).join('')}</div>
  </div>
</section>`;}
function parseRoute(){const [path='/',query='']=(location.hash.slice(1)||'/').split('?');return {path,params:new URLSearchParams(query)};}
function readFilters(params){return {query:params.get('q')||'',category:params.get('category')||'All',platform:params.get('platform')||'All',minimumStars:params.get('stars')||0,selfHosted:params.get('selfHosted')==='1',trending:params.get('trending')==='1',openOnly:params.get('openOnly')==='1',reviewed:params.get('reviewed')==='1',sort:params.get('sort')||'featured'};}
function sorted(projectList,sort){return [...projectList].sort((a,b)=>sort==='stars'?(b.stars||0)-(a.stars||0):sort==='new'?new Date(b.createdAt)-new Date(a.createdAt):sort==='trending'?(b.weeklyStars||0)-(a.weeklyStars||0):sort==='reviews'?(b.review?.count||0)-(a.review?.count||0):sort==='rating'?(b.review?.rating||0)-(a.review?.rating||0)||(b.review?.count||0)-(a.review?.count||0):sort==='name'?a.name.localeCompare(b.name):0);}
function empty(query=''){const value=encodeURIComponent(query);return `<div class="empty-state zero-results">${svg('search')}<h2>No curated match yet.</h2><p>OpenStore’s catalog is reviewed by hand. Help the discovery pipeline without lowering that bar.</p><div class="zero-result-actions">${query?`<a class="button button-primary" href="#/submit?alternative=${value}">Know an alternative? Submit it</a><a class="button button-secondary" href="#/wanted?product=${value}">Looking for one too? Request an alternative</a>`:'<button class="button button-primary" data-action="reset-filters">Clear all filters</button><a class="button button-secondary" href="#/">Back to Discover</a>'}</div></div>`;}
function browse(route){const f=readFilters(route.params);const isTrending=route.path==='/trending',isNew=route.path==='/new';if(isTrending)f.trending=true;const defaultSort=isTrending?'trending':isNew?'new':f.sort;const list=sorted(filterProjects(projects,f),route.params.get('sort')||defaultSort);const resultKey=route.path+'?'+route.params.toString();if(resultKey!==lastResultKey){visibleLimit=24;lastResultKey=resultKey;}const title=f.query?`Results for “${esc(f.query)}”`:f.openOnly?'The Open family':f.reviewed?'Well reviewed':isTrending?'Trending this week':isNew?'Newest projects':f.category!=='All'?esc(f.category):'All apps';const subtitle=isTrending?`Real momentum from GitHub’s weekly Trending page. Snapshot ${date(trendSnapshot.fetchedAt)}.`:isNew?'Sorted by repository creation date.':'Curated open-source alternatives to the software you already use.';
const chips=activeFilters(f,isTrending);const advancedCount=chips.filter(c=>['stars','trending','openOnly','reviewed'].includes(c.key)).length;
return `<section class="explore-intro browse-intro"><div><span class="eyebrow">${isTrending?'GitHub Trending':isNew?'Newest':'Browse'}</span><h1>${title}</h1><p>${subtitle}</p></div></section><section class="browse-controls" aria-label="Browse controls"><div class="browse-toolbar">${searchBox(f.query)}<label class="filter-select platform-select"><select aria-label="Filter by platform" name="platform" data-filter="platform">${['All','macOS','Windows','Linux','Web','iOS','Android'].map(v=>`<option value="${v}" ${f.platform===v?'selected':''}>${v==='All'?'All platforms':v}</option>`).join('')}</select></label><button class="filter-trigger ${advancedCount?'has-filters':''}" data-action="open-filters" aria-haspopup="dialog">${svg('sliders')}Filters${advancedCount?`<span class="filter-count">${advancedCount}</span>`:''}</button><label class="filter-select sort-select"><select aria-label="Sort projects" name="sort" data-filter="sort">${[['featured','Curated'],['stars','Most stars'],['reviews','Most reviews'],['rating','Top rated'],['trending','Momentum'],['new','Newest'],['name','Name A–Z']].map(([v,t])=>`<option value="${v}" ${(route.params.get('sort')||defaultSort)===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="category-pills" aria-label="Filter by category">${['All',...categories.map(c=>c.name)].map(c=>`<button class="category-pill ${f.category===c?'active':''}" data-category="${esc(c)}" aria-pressed="${f.category===c}">${c!=='All'?svg(categories.find(x=>x.name===c).icon):svg('layers')}${esc(c==='All'?'All apps':c)}</button>`).join('')}</div></section><div class="results-heading"><div class="results-summary"><strong>${list.length} ${list.length===1?'app':'apps'} to explore</strong><button class="selfhost-toggle" data-action="toggle-selfhost" aria-pressed="${f.selfHosted}">${svg('server')}Self-hosted</button></div>${chips.length?'<button class="text-link" data-action="reset-filters">Reset filters</button>':''}</div>${chips.length?`<div class="active-filters" aria-label="Active filters">${chips.map(c=>`<button data-remove-filter="${c.key}" aria-label="Remove ${esc(c.label)} filter">${esc(c.label)}<span aria-hidden="true">×</span></button>`).join('')}</div>`:''}<div class="catalog-grid" id="results">${list.length?list.slice(0,visibleLimit).map(card).join(''):empty(f.query)}</div>${list.length>visibleLimit?`<div class="load-more"><p>Showing ${Math.min(visibleLimit,list.length)} of ${list.length} apps</p><button class="button button-secondary" data-action="load-more">Show more apps ${svg('chevron')}</button></div>`:''}<p class="detail-snapshot">Stars from GitHub · ${date(snapshot.fetchedAt)}. ${isNew?'Repository age does not imply product maturity.':'Comparisons describe overlapping use cases, not feature parity.'}</p>`;}
function activeFilters(f,isTrending=false){return [f.query&&{key:'q',label:`Search: ${f.query}`},f.category!=='All'&&{key:'category',label:f.category},f.platform!=='All'&&{key:'platform',label:f.platform},Number(f.minimumStars)>0&&{key:'stars',label:`${compact(Number(f.minimumStars))}+ stars`},f.selfHosted&&{key:'selfHosted',label:'Self-hosted'},!isTrending&&f.trending&&{key:'trending',label:'Recently trending'},f.openOnly&&{key:'openOnly',label:'Open… apps'},f.reviewed&&{key:'reviewed',label:'With user reviews'}].filter(Boolean);}
function openFilters(){const route=parseRoute(),f=readFilters(route.params),dialog=document.querySelector('#filter-dialog');dialog.querySelector('#filter-options').innerHTML=`<label class="sheet-select"><span>Minimum GitHub stars</span><select name="stars">${[[0,'Any stars'],[1000,'1,000+ stars'],[10000,'10,000+ stars'],[50000,'50,000+ stars'],[100000,'100,000+ stars']].map(([v,t])=>`<option value="${v}" ${Number(f.minimumStars)===v?'selected':''}>${t}</option>`).join('')}</select></label>${[['selfHosted','Self-hosted','Run it on infrastructure you control.'],...route.path==='/trending'?[]:[['trending','Recently trending','On GitHub’s weekly Trending page.']],['openOnly','Open… apps','Projects with names that start with Open.'],['reviewed','With user reviews','Published ratings with a verified source.']].map(([key,label,help])=>`<label class="sheet-check"><span><strong>${label}</strong><small>${help}</small></span><input type="checkbox" name="${key}" ${f[key]?'checked':''}></label>`).join('')}`;dialog.showModal();}

function categoryPage(){return `<section class="explore-intro"><div><h1>Categories</h1><p>Every app in the collection, grouped by what it helps you do.</p></div>${searchBox()}</section><div class="category-directory">${categories.map(c=>categoryCard(c,true)).join('')}</div>${heading('Good places to start','','#/browse','All apps')}<div class="apps-grid">${['opencode','open-webui','appflowy','actual','penpot','openproject'].map(id=>row(projects.find(p=>p.id===id))).join('')}</div>`;}
function authNotice(next,copy='Sign in with GitHub to vote.'){return `<div class="auth-notice">${svg('github')}<div><strong>${copy}</strong><p>Browsing and app submissions are open to everyone. Sign-in keeps votes to one per person.</p></div><button class="button button-primary" data-action="sign-in" data-next="${esc(next)}">Sign in with GitHub</button>${location.hostname==='localhost'?'<button class="text-link" data-action="dev-sign-in">Local admin sign-in</button>':''}</div>`;}
function userStrip(){return currentUser?`<div class="user-strip">${currentUser.avatarUrl?`<img src="${esc(currentUser.avatarUrl)}" alt="" width="28" height="28">`:svg('user')}<span>Signed in as <strong>${esc(currentUser.login)}</strong></span>${currentUser.isAdmin?'<a href="#/admin">Review queue</a>':''}<button class="text-link" data-action="sign-out">Sign out</button></div>`:'';}
function statusBadge(status){return `<span class="moderation-badge status-${esc(status)}">${status==='approved'?'Accepted for consideration':status==='rejected'?'Rejected':'Awaiting review'}</span>`;}
function communityCard(item){const meta=item.metadata||{};return `<article class="community-card"><div class="community-card-head">${meta.ownerAvatarUrl?`<span class="app-icon image-icon"><img src="${esc(meta.ownerAvatarUrl)}" alt="" width="48" height="48"></span>`:`<span class="app-icon">${svg('layers')}</span>`}<div><div class="community-card-label">${statusBadge(item.status)}<span>${esc(item.category)}</span><span>Submitted ${date(item.createdAt)}</span></div><h2>${esc(item.name)}</h2><p>${esc(item.repo)}</p></div></div><p class="community-description">${esc(item.description)}</p><div class="community-signals"><span>${svg('star')}<strong>${compact(meta.stars)}</strong> stars</span><span>${svg('fork')}<strong>${compact(meta.forks)}</strong> forks</span>${meta.language?`<span>${esc(meta.language)}</span>`:''}</div><div class="replacement-chip"><span>Suggested alternative to</span><b>${esc(item.alternatives.join(' · '))}</b></div><div class="community-card-foot"><button class="recommend-button" data-action="recommend" data-id="${item.id}" aria-pressed="${item.recommendedByViewer}" aria-label="${item.recommendedByViewer?'Remove your vote from':'Vote for'} ${esc(item.name)}">${svg('thumbs')}<span>${item.recommendedByViewer?'Voted':'Vote'}</span><strong>${item.recommendationCount}</strong></button><div><a class="text-link" href="${esc(item.repoUrl)}" ${externalAttrs}>GitHub ${svg('external')}</a></div></div><details class="community-feedback"><summary>${item.feedbackCount} ${item.feedbackCount===1?'note':'notes'} for editors · ${item.feedbackByViewer?'Edit your note':'Share feedback'}</summary>${currentUser?`<form class="feedback-form" data-id="${item.id}"><label><span>What should editors know?</span><textarea name="note" maxlength="500" rows="3" required placeholder="Share what works well or what needs a closer look.">${esc(item.feedbackByViewer)}</textarea></label><div class="form-feedback" role="alert"></div><button class="button button-secondary" type="submit">${item.feedbackByViewer?'Update note':'Send feedback'}</button></form>`:`<button class="text-link" data-action="sign-in" data-next="#/community">Sign in to share feedback</button>`}</details></article>`;}
function communityPage(){const pending=communitySubmissions.filter(item=>item.status==='pending'),approved=communitySubmissions.filter(item=>item.status==='approved');return `<section class="community-hero"><div><span class="eyebrow">Community Finds</span><h1>Promising projects, discovered together.</h1><p>Recent submissions and community votes help you spot useful projects. OpenStore’s curated catalog changes only after a separate manual review.</p></div><div class="community-hero-actions"><a class="button button-primary" href="#/submit">Submit a project ${svg('arrow')}</a><a class="button button-secondary" href="#/wanted">Wanted alternatives</a></div></section>${userStrip()}${!currentUser?authNotice('#/community','Sign in to vote or share feedback.'):''}${communityError?`<div class="inline-state error-state"><strong>Community Finds couldn’t load.</strong><p>${esc(communityError)}</p><button class="button button-secondary" data-action="reload-community">Try again</button></div>`:pending.length?`<section class="section compact-section">${heading('Recent submissions',`${pending.length} awaiting review · newest first`)}<div class="community-grid">${pending.map(communityCard).join('')}</div></section>`:`<div class="inline-state">${svg('inbox')}<strong>No pending community finds.</strong><p>Be the first to share a promising open-source project.</p><a class="button button-primary" href="#/submit">Submit an app</a></div>`}${approved.length?`<section class="section compact-section">${heading('Accepted for consideration','Reviewed projects that may be added to the curated catalog later.')}<div class="community-grid">${approved.map(communityCard).join('')}</div></section>`:''}`;}
function field(label,name,content,help=''){return `<label class="form-field"><span>${label}</span>${content}${help?`<small>${help}</small>`:''}</label>`;}
function submitPage(route){
 const alternative=route.params.get('alternative')||'',repo=route.params.get('repo')||'';
 const steps=[['Listed in Community Finds','Your project appears there as pending as soon as you submit.'],['Community signal','Signed-in visitors can vote for it and leave notes for editors.'],['Editorial review','Editors accept or decline it. Accepted projects join the curated catalog in a separate, manual update.']];
 return `<div class="submit-page"><header class="submit-head"><span class="eyebrow">Contribute</span><h1>Submit a project</h1><p>Suggest an open-source app for OpenStore. Paste its GitHub repository and we’ll fill in what we can. No account needed.</p></header>${userStrip()}<div class="submit-layout"><form class="submit-form" id="submission-form"><div class="bot-field" aria-hidden="true"><label>Company<input name="company" tabindex="-1" autocomplete="off"></label></div>
 <section class="submit-section"><div class="submit-section-head"><h2>Repository</h2><p>Public repositories on github.com only.</p></div><div class="form-field"><label for="submit-repo-url">GitHub repository URL</label><div class="input-action"><div class="repo-input">${svg('github')}<input id="submit-repo-url" required type="url" name="repoUrl" value="${esc(repo)}" placeholder="https://github.com/owner/project" autocomplete="url" spellcheck="false"></div><button type="button" class="button button-secondary" data-action="fetch-metadata">Fetch details</button></div><small>Name, description, and website are filled from GitHub when you paste a link.</small></div><div class="metadata-preview" id="metadata-preview" aria-live="polite" hidden></div></section>
 <section class="submit-section"><div class="submit-section-head"><h2>Project details</h2><p>Where it fits and what it replaces.</p></div><div class="submit-fields">${field('Project name','name','<input required name="name" maxlength="100" placeholder="e.g. AppFlowy">')}${field('Category','category',`<select required name="category"><option value="">Choose a category</option>${categories.map(c=>`<option>${esc(c.name)}</option>`).join('')}</select>`)}${field('Alternative to','alternatives',`<input required name="alternatives" maxlength="240" value="${esc(alternative)}" placeholder="e.g. Notion, Confluence">`,'Proprietary products it can replace, separated by commas.')}${field('Short description','description','<textarea required name="description" maxlength="320" rows="3" placeholder="What does this project help people do?"></textarea>','<span>One or two plain sentences.</span><span class="char-count" data-count="description">0 / 320</span>')}<fieldset class="submit-platforms"><legend>Available on <small>Choose at least one</small></legend><div class="platform-options">${['Web','macOS','Windows','Linux','iOS','Android'].map(value=>`<label><input type="checkbox" name="platforms" value="${value}">${svg('check')}${value}</label>`).join('')}</div></fieldset></div></section>
 <details class="submit-optional"><summary><span><strong>More details</strong><small>Optional · website, docs, audience, self-hosting</small></span>${svg('chevron')}</summary><div class="submit-fields">${field('Website','websiteUrl','<input type="url" name="websiteUrl" placeholder="https://project.example">')}${field('Documentation','docsUrl','<input type="url" name="docsUrl" placeholder="https://docs.project.example">')}${field('Best for','bestFor','<input name="bestFor" maxlength="160" placeholder="e.g. Small teams that want to own their notes">')}${field('Important consideration','consideration','<textarea name="consideration" maxlength="400" rows="3" placeholder="A limitation or setup detail people should know"></textarea>')}<label class="check-field"><input type="checkbox" name="selfHosted"><span><strong>Self-hosting available</strong><small>Users can deploy and operate the project themselves.</small></span></label></div></details>
 <div class="form-feedback" role="alert"></div><div class="submit-footer"><a class="text-link" href="#/community">Cancel</a><button class="button button-primary" type="submit">Submit project</button></div></form>
 <aside class="submit-aside" aria-label="How review works"><h2>What happens next</h2><ol class="submit-steps">${steps.map(([title,copy])=>`<li><strong>${title}</strong><p>${copy}</p></li>`).join('')}</ol><div class="submit-aside-note"><h3>Good to know</h3><ul><li>Projects already in the catalog, or submitted before, can’t be added twice.</li><li>Looking for an alternative rather than suggesting one? <a href="#/wanted">Request it</a>.</li></ul></div></aside></div></div>`;
}
function solutionLabel(solution){if(solution.catalogId){const app=catalogChoiceList.find(item=>item.id===solution.catalogId);return app?`OpenStore · ${app.name}`:solution.catalogId;}return solution.metadata?.fullName||solution.githubUrl||'GitHub project';}
function wantedCard(item){return `<article class="wanted-card"><div class="wanted-rank"><button data-action="vote-wanted" data-id="${item.id}" aria-pressed="${item.votedByViewer}" aria-label="${item.votedByViewer?'Remove vote from':'Vote for'} ${esc(item.productName)}">${svg('chevron')}<strong>${item.voteCount}</strong><span>wanted</span></button></div><div class="wanted-copy"><div>${item.status==='resolved'?'<span class="moderation-badge status-approved">Resolved</span>':'<span class="moderation-badge status-pending">Open request</span>'}<span class="wanted-author">Requested by @${esc(item.submitter.login)}</span></div><h2>Alternative to ${esc(item.productName)}</h2>${item.description?`<p>${esc(item.description)}</p>`:''}${item.solutions.length?`<div class="solution-list"><strong>${item.solutions.length} suggested ${item.solutions.length===1?'solution':'solutions'}</strong>${item.solutions.map(solution=>`<span>${svg('check')}${esc(solutionLabel(solution))}</span>`).join('')}</div>`:''}${item.status==='open'?`<details class="solution-form-wrap"><summary>Suggest a solution</summary><form class="solution-form" data-request-id="${item.id}"><label><span>Existing OpenStore app</span><select name="catalogId"><option value="">Choose an app</option>${catalogChoiceList.map(app=>`<option value="${esc(app.id)}">${esc(app.name)}</option>`).join('')}</select></label><span class="form-or">or</span><label><span>GitHub repository</span><input type="url" name="githubUrl" placeholder="https://github.com/owner/project"></label><div class="form-feedback" role="alert"></div><button class="button button-secondary" type="submit">Suggest solution</button></form></details>`:''}</div></article>`;}
function wantedPage(route){const product=route.params.get('product')||'',open=wantedRequests.filter(item=>item.status==='open'),resolved=wantedRequests.filter(item=>item.status==='resolved');return `<section class="community-hero wanted-hero"><div><span class="eyebrow">Wanted alternatives</span><h1>What should open source replace next?</h1><p>Request an alternative, vote on existing needs, and connect requests with useful projects. Duplicate requests become votes so the strongest needs rise.</p></div></section>${userStrip()}${currentUser?`<form class="wanted-request-form" id="wanted-form"><div>${field('Product to replace','productName',`<input required name="productName" maxlength="100" value="${esc(product)}" placeholder="Lightroom">`)}${field('What matters most?','description','<input name="description" maxlength="400" placeholder="Photo organization and non-destructive editing">')}</div><div class="form-feedback" role="alert"></div><button class="button button-primary" type="submit">Request an alternative ${svg('arrow')}</button></form>`:authNotice(`#/wanted${product?'?product='+encodeURIComponent(product):''}`,'Sign in to request or vote for an alternative.')}${wantedError?`<div class="inline-state error-state"><strong>Wanted alternatives couldn’t load.</strong><p>${esc(wantedError)}</p><button class="button button-secondary" data-action="reload-wanted">Try again</button></div>`:open.length?`<section class="section compact-section">${heading('Most wanted, still open',`${open.length} unresolved ${open.length===1?'request':'requests'}, ranked by community demand.`)}<div class="wanted-list">${open.map(wantedCard).join('')}</div></section>`:`<div class="inline-state"><strong>No open requests yet.</strong><p>Start with a product you wish had an open alternative.</p></div>`}${resolved.length?`<section class="section compact-section">${heading('Resolved by the community','Requests with a suggested match.')}<div class="wanted-list">${resolved.map(wantedCard).join('')}</div></section>`:''}`;}
function adminCard(item){
 const meta=item.metadata||{};
 return `<form class="moderation-card moderation-form" data-id="${item.id}">
 <div class="moderation-head"><div>${statusBadge(item.status)}<h2>${esc(item.name)}</h2><a href="${esc(item.repoUrl)}" ${externalAttrs}>${esc(item.repo)} ${svg('external')}</a><p class="admin-submitted">Submitted ${date(item.createdAt)} · ${item.submitter.login==='Guest'?'Guest submission':`@${esc(item.submitter.login)}`}</p></div><div class="admin-signals"><span>${svg('thumbs')}<strong>${item.recommendationCount}</strong> community ${item.recommendationCount===1?'vote':'votes'}</span><span>${svg('star')} ${compact(meta.stars)} GitHub stars</span></div></div>
 <p class="admin-description">${esc(item.description)}</p><p class="admin-alternatives">Alternative to ${esc(item.alternatives.join(', '))}</p><div class="admin-repo-facts"><span>${esc(meta.license||'License unverified')}</span><span>Last push ${date(meta.pushedAt)}</span>${meta.archived?'<span class="admin-archived">Archived repository</span>':''}</div>${item.voters?.length?`<details class="admin-voters"><summary>See ${item.voters.length} ${item.voters.length===1?'voter':'voters'}</summary><div>${item.voters.map(voter=>`<span>@${esc(voter.login)} · ${date(voter.votedAt)}</span>`).join('')}</div></details>`:'<p class="admin-no-votes">No community votes yet.</p>'}<div class="admin-feedback"><strong>Community feedback · ${item.feedback?.length||0}</strong>${item.feedback?.length?item.feedback.map(entry=>`<p><span>@${esc(entry.login)} · ${date(entry.updatedAt)}</span>${esc(entry.note)}</p>`).join(''):'<p>No feedback notes yet.</p>'}</div>
 <details class="admin-editor"><summary>Review details and edit</summary><div class="admin-fields">${field('Name','name',`<input name="name" value="${esc(item.name)}" required>`)}${field('Category','category',`<select name="category">${categories.map(c=>`<option ${c.name===item.category?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`)}${field('Description','description',`<textarea name="description" rows="3" required>${esc(item.description)}</textarea>`)}${field('Alternative to','alternatives',`<input name="alternatives" value="${esc(item.alternatives.join(', '))}" required>`)}${field('Platforms','platforms',`<input name="platforms" value="${esc(item.platforms.join(', '))}" required>`)}${field('Website','websiteUrl',`<input type="url" name="websiteUrl" value="${esc(item.websiteUrl)}">`)}${field('Best for','bestFor',`<input name="bestFor" value="${esc(item.bestFor)}">`)}${field('Consideration','consideration',`<textarea name="consideration" rows="2">${esc(item.consideration)}</textarea>`)}${field('Moderator note','moderatorNote',`<textarea name="moderatorNote" rows="2">${esc(item.moderatorNote)}</textarea>`)}<label class="check-field"><input type="checkbox" name="selfHosted" ${item.selfHosted?'checked':''}><span><strong>Self-hosted</strong></span></label></div><div class="form-feedback" role="alert"></div><div class="moderation-actions"><button class="button button-secondary reject-action" type="submit" name="status" value="rejected" formnovalidate>Reject</button><button class="button button-secondary" type="submit" name="status" value="${esc(item.status)}">Save edits</button><button class="button button-primary" type="submit" name="status" value="approved">Accept for consideration</button></div></details>
 </form>`;
}
function adminWantedCard(item){return `<form class="moderation-card wanted-resolution-form" data-id="${item.id}"><div class="moderation-head"><div><span class="moderation-badge status-pending">${item.voteCount} wanted</span><h2>Alternative to ${esc(item.productName)}</h2><p>${esc(item.description)}</p></div></div><label class="form-field"><span>Accepted solution</span><select name="solutionId" required><option value="">Choose a community suggestion</option>${item.solutions.map(solution=>`<option value="${solution.id}">${esc(solutionLabel(solution))}</option>`).join('')}</select></label><div class="form-feedback" role="alert"></div><div class="moderation-actions"><button class="button button-primary" type="submit">Mark resolved</button></div></form>`;}
function adminPage(){
 if(!currentUser)return `<section class="form-page-head"><span class="eyebrow">Editorial review</span><h1>Submission review.</h1><p>See community votes, review every submission, and decide which projects deserve further consideration.</p></section>${authNotice('#/admin','Sign in with your editor account to review submissions.')}`;
 if(!currentUser.isAdmin)return `<div class="empty-state">${svg('shield')}<h2>Admin access required.</h2><p>This panel is available to configured OpenStore editors.</p><a class="button button-secondary" href="#/community">Back to Community Finds</a></div>`;
 if(adminQueue===null)return `<div class="loading"><img class="brand-mark" src="/assets/logo.svg" alt=""><p>Loading submissions…</p></div>`;
 if(adminError)return `<section class="form-page-head"><span class="eyebrow">Editorial review</span><h1>Submission review.</h1></section><div class="inline-state error-state"><strong>Submissions couldn’t load.</strong><p>${esc(adminError)}</p><button class="button button-secondary" data-action="reload-admin">Try again</button></div>`;
 const filters=[['all','All submissions'],['pending','Pending'],['approved','Accepted'],['rejected','Rejected']];
 const selected=adminFilter==='all'?adminQueue:adminQueue.filter(item=>item.status===adminFilter);
 const resolvable=wantedRequests.filter(item=>item.status==='open'&&item.solutions.length);
 return `<section class="form-page-head"><span class="eyebrow">Editorial review</span><h1>Submission review.</h1><p>Votes and GitHub signals help with evaluation. Accepting a project keeps it in Community Finds; you add it to the curated catalog manually later.</p></section>${userStrip()}<div class="admin-overview">${[['pending','Awaiting review'],['approved','Accepted for later'],['rejected','Rejected'],['all','Total submissions']].map(([status,label])=>`<div><strong>${status==='all'?adminQueue.length:adminQueue.filter(item=>item.status===status).length}</strong><span>${label}</span></div>`).join('')}</div><div class="admin-filter-row" aria-label="Filter submissions">${filters.map(([status,label])=>`<button data-action="admin-filter" data-status="${status}" aria-pressed="${adminFilter===status}">${label}</button>`).join('')}</div><div class="admin-list-heading"><h2>${filters.find(([status])=>status===adminFilter)?.[1]}</h2><span>${selected.length} shown · recent submissions first</span></div><div class="moderation-list">${selected.length?selected.map(adminCard).join(''):'<div class="inline-state"><strong>No submissions in this view.</strong><p>New projects will appear here after they are submitted.</p></div>'}</div>${resolvable.length?`<section class="section compact-section">${heading('Wanted requests with solutions','Choose a community suggestion to resolve each request.')}<div class="moderation-list">${resolvable.map(adminWantedCard).join('')}</div></section>`:''}`;
}
function details(id){const p=projects.find(p=>p.id===id);if(!p)return `<div class="empty-state">${svg('layers')}<h1>That app isn’t in our collection.</h1><p>There are plenty of other possibilities to explore.</p><a class="button button-primary" href="#/">Back to Discover</a></div>`;const related=projects.filter(x=>x.id!==p.id&&x.category===p.category).slice(0,3);const repository=snapshot.repositories?.[p.repo];return `<div class="breadcrumbs"><a href="#/">Discover</a>${svg('chevron')}<a href="#/browse?category=${encodeURIComponent(p.category)}">${esc(p.category)}</a>${svg('chevron')}<span>${esc(p.name)}</span></div><section class="detail-hero">${icon(p)}<div><span class="eyebrow">${esc(p.category)}</span><h1>${esc(p.name)}</h1><p>${esc(p.description)}</p><div class="detail-tags"><span>${p.sourceAvailable?'Source-available':'Open source'}</span><span>·</span><span>${p.selfHosted?'Self-hosting available':'Runs on your device'}</span></div></div><div class="detail-actions"><a class="button button-primary" href="${esc(p.website)}" ${externalAttrs}>Get ${esc(p.name)} ${svg('external')}</a><a class="button button-secondary" href="${gh(p)}" ${externalAttrs}>${svg('github')}GitHub</a><button class="icon-button save-button" data-save="${p.id}" aria-label="${saved.has(p.id)?'Unsave':'Save'} ${esc(p.name)}" aria-pressed="${saved.has(p.id)}" title="${saved.has(p.id)?'Saved to this browser':'Save to this browser'}">${svg('bookmark')}</button></div></section><section class="detail-stats" aria-label="Project information"><div class="detail-stat"><span>GitHub stars</span><strong>${svg('star')}${compact(p.stars)}</strong><small>${exact(p.stars)} stars</small></div><div class="detail-stat"><span>Community forks</span><strong>${svg('fork')}${compact(p.forks)}</strong><small>Open collaboration</small></div><div class="detail-stat"><span>License</span><strong class="detail-stat-text">${esc(p.license)}</strong><small>${p.sourceAvailable?'Branding conditions apply':'Read the full license'}</small></div><div class="detail-stat"><span>Platforms</span><strong class="detail-stat-text">${esc(p.platforms.slice(0,3).join(' · '))}</strong><small>${p.platforms.length>3?`Also ${esc(p.platforms.slice(3).join(', '))}`:'Find your platform'}</small></div><div class="detail-stat"><span>${p.weeklyStars?'Weekly stars':'Last activity'}</span><strong>${p.weeklyStars?'↗ '+compact(p.weeklyStars):date(p.updatedAt).replace(', 2026','')}</strong><small>${p.weeklyStars?'GitHub trending snapshot':'Repository push date'}</small></div></section>
${p.screens.length?`<section class="screenshot-section"><div class="screenshot-heading"><h2>Screenshots</h2><span>Official project imagery</span></div><div class="screenshot-gallery">${p.screens.map(([file,alt])=>`<button class="screenshot-button" data-image="${esc(file)}" data-caption="${esc(alt)}" aria-label="Expand ${esc(alt)}"><img src="assets/${esc(file)}" alt="${esc(alt)}" width="1000" height="550"></button>`).join('')}</div></section>`:`<section class="product-resource"><div><h3>See ${esc(p.name)} in action.</h3><p>Explore the project’s official website and documentation.</p></div><a class="button button-secondary" href="${esc(p.website)}" ${externalAttrs}>Visit project ${svg('external')}</a></section>`}
${evidence(p)}<div class="detail-body"><section><h2>About ${esc(p.name)}</h2><p>${esc(p.about)}</p><ul>${p.features.map(x=>`<li>${svg('check')}${esc(x)}</li>`).join('')}</ul>${p.note?`<div class="license-note">${esc(p.note)} <a href="${esc(p.licenseUrl||gh(p))}" ${externalAttrs}>Read more ↗</a></div>`:''}<h2 class="detail-subheading">Alternative to</h2><div class="alternative-chips">${p.replaces.map(x=>`<span>${esc(x)}</span>`).join('')}</div><p class="detail-snapshot">These tools share use cases. Features, costs, and deployment needs differ.</p></section><aside class="detail-info"><h3>Details</h3><dl><div><dt>Category</dt><dd><a href="#/browse?category=${encodeURIComponent(p.category)}">${esc(p.category)}</a></dd></div><div><dt>Available on</dt><dd>${esc(p.platforms.join(', '))}</dd></div><div><dt>License</dt><dd><a href="${esc(p.licenseUrl||`${gh(p)}#license`)}" ${externalAttrs}>${esc(p.license)} ↗</a></dd></div><div><dt>Self-hosted</dt><dd>${p.selfHosted?'Available':'Not a hosted server app'}</dd></div><div><dt>Repository</dt><dd><a href="${gh(p)}" ${externalAttrs}>${esc(p.repo)} ↗</a></dd></div><div><dt>Created</dt><dd>${date(p.createdAt)}</dd></div></dl><a class="text-link" href="${esc(p.docs)}" ${externalAttrs}>Read the documentation ${svg('external')}</a><a class="text-link" href="${gh(p)}/issues" ${externalAttrs}>Community & issues ${svg('external')}</a><p class="detail-snapshot">GitHub stats captured ${date(snapshot.fetchedAt)}.</p></aside></div>
${related.length?`<section class="section categories-section">${heading(`More in ${esc(p.category)}`,'',`#/browse?category=${encodeURIComponent(p.category)}`,'See category')}<div class="apps-grid">${related.map(row).join('')}</div></section>`:''}<a class="back-button" href="#/">${svg('back')}Back to Discover</a>`;}
function render(scroll=true){const route=parseRoute();const oldSearch=document.activeElement?.id==='app-search';const selection=document.activeElement?.selectionStart;const focused=document.activeElement;const filterFocus=focused?.dataset.filter;const actionFocus=focused?.dataset.action;const categoryFocus=focused?.dataset.category;const railLeft=main.querySelector('.category-pills')?.scrollLeft||0;const pages={'/':()=>home(),'/categories':()=>categoryPage(),'/community':()=>communityPage(),'/submit':()=>submitPage(route),'/wanted':()=>wantedPage(route),'/admin':()=>adminPage(),'/auth-error':()=>`<div class="empty-state">${svg('info')}<h2>Sign-in didn’t finish.</h2><p>${esc(route.params.get('message')||'Try signing in again.')}</p><a class="button button-primary" href="#/community">Back to Community Finds</a></div>`};main.innerHTML=route.path.startsWith('/app/')?details(decodeURIComponent(route.path.slice(5))):(pages[route.path]?.()||browse(route));document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(route.path==='/categories'?'categories':route.path==='/trending'?'trending':route.path==='/new'?'new':route.path==='/'?'discover':'')));document.querySelector('.submit-nav')?.classList.toggle('active',route.path==='/submit');const p=projects.find(p=>route.path==='/app/'+p.id);const pageTitles={'/categories':'Categories','/trending':'Trending','/new':'New','/community':'Community Finds','/submit':'Submit an App','/wanted':'Wanted Alternatives','/admin':'Editorial Review'};document.title=p?`${p.name} — OpenStore`:`${pageTitles[route.path]||'OpenStore'}${route.path==='/'?' — Great software. Open possibilities.':' — OpenStore'}`;if(oldSearch&&!scroll){const input=document.querySelector('#app-search');if(input){input.focus();try{input.setSelectionRange(selection,selection);}catch{}}}const rail=main.querySelector('.category-pills');if(rail){rail.scrollLeft=railLeft;rail.querySelector('.active')?.scrollIntoView({block:'nearest',inline:'nearest'});}if(!scroll&&!oldSearch){const target=filterFocus?main.querySelector(`[data-filter="${filterFocus}"]`):actionFocus?main.querySelector(`[data-action="${actionFocus}"]`):categoryFocus?main.querySelector(`[data-category="${CSS.escape(categoryFocus)}"]`):null;target?.focus({preventScroll:true});}if(scroll)window.scrollTo({top:0,behavior:'instant'});if(route.path==='/admin'&&currentUser?.isAdmin&&adminQueue===null&&!adminLoading)loadAdmin();}
async function api(path,options={}){const response=await fetch(path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});const data=await response.json().catch(()=>({}));if(!response.ok){const error=new Error(data.error||'Something went wrong.');error.code=data.code;error.status=response.status;throw error;}return data;}
function signIn(next=location.hash||'#/'){location.href=`/api/auth/github?next=${encodeURIComponent(next)}`;}
async function refreshCommunity(){try{const data=await api('/api/community');communitySubmissions=data.submissions;communityError='';}catch(error){communityError=error.message;}if(parseRoute().path==='/community')render(false);}
async function refreshWanted(){try{const data=await api('/api/wanted');wantedRequests=data.requests;wantedError='';}catch(error){wantedError=error.message;}if(parseRoute().path==='/wanted')render(false);}
async function loadAdmin(){adminLoading=true;adminError='';try{const data=await api('/api/admin/submissions');adminQueue=data.submissions;}catch(error){adminQueue=[];adminError=error.message;}finally{adminLoading=false;if(parseRoute().path==='/admin')render(false);}}
function updateFilter(key,value,{replace=false}={}){const route=parseRoute();const path=route.path==='/'||route.path==='/categories'||route.path.startsWith('/app/')?'/browse':route.path;const params=route.params;if(value===null||value===''||value==='All'||value==='0')params.delete(key);else params.set(key,value);const hash=`#${path}${params.size?'?'+params.toString():''}`;if(replace){history.replaceState(null,'',hash);render(false);}else{history.pushState(null,'',hash);render(false);}}
function toast(message){const box=document.querySelector('#toast');box.textContent=message;box.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.classList.remove('visible'),2600);}
main.addEventListener('input',e=>{if(e.target.id==='app-search')updateFilter('q',e.target.value,{replace:true});});
main.addEventListener('change',e=>{if(e.target.dataset.filter){updateFilter(e.target.dataset.filter,e.target.type==='checkbox'?(e.target.checked?'1':null):e.target.value);}});
main.addEventListener('click',async e=>{const category=e.target.closest('[data-category]');if(category){updateFilter('category',category.dataset.category);return;}const search=e.target.closest('[data-search]');if(search){location.hash='/browse?q='+encodeURIComponent(search.dataset.search);return;}const remove=e.target.closest('[data-remove-filter]');if(remove){updateFilter(remove.dataset.removeFilter,null);main.querySelector('[data-action="open-filters"]')?.focus({preventScroll:true});return;}const control=e.target.closest('[data-action]'),action=control?.dataset.action;if(action==='admin-filter'){adminFilter=control.dataset.status;render(false);return;}if(action==='sign-in'){signIn(control.dataset.next);return;}if(action==='dev-sign-in'){try{const data=await api('/api/auth/dev',{method:'POST'});currentUser=data.user;adminQueue=null;await Promise.all([refreshCommunity(),refreshWanted()]);render();}catch(error){toast(error.message);}return;}if(action==='sign-out'){await api('/api/auth/logout',{method:'POST'});currentUser=null;adminQueue=null;await Promise.all([refreshCommunity(),refreshWanted()]);render(false);return;}if(action==='reload-community'){await refreshCommunity();return;}if(action==='reload-wanted'){await refreshWanted();return;}if(action==='fetch-metadata'){const form=control.closest('form'),preview=form.querySelector('#metadata-preview'),repo=form.elements.repoUrl.value;control.disabled=true;control.textContent='Fetching…';try{const data=await api(`/api/github?repo=${encodeURIComponent(repo)}`);form.elements.name.value||=data.metadata.name;form.elements.description.value||=data.metadata.description;form.elements.websiteUrl.value||=data.metadata.homepage;form.elements.description.dispatchEvent(new Event('input',{bubbles:true}));const meta=data.metadata;preview.hidden=false;preview.classList.remove('is-error');preview.innerHTML=`${meta.ownerAvatarUrl?`<img src="${esc(meta.ownerAvatarUrl)}" alt="" width="32" height="32">`:svg('github')}<div><strong>${esc(meta.fullName)}</strong><span>${exact(meta.stars)} stars · ${exact(meta.forks)} forks${meta.license?' · '+esc(meta.license):''}${meta.language?' · '+esc(meta.language):''}</span></div><span class="metadata-status">${svg('check')}Details filled</span>${meta.archived?'<p class="metadata-warning">This repository is archived on GitHub, so it may no longer be maintained.</p>':''}`;}catch(error){preview.hidden=false;preview.classList.add('is-error');preview.innerHTML=`${svg('info')}<span class="field-error">${esc(error.message)}</span>`;}finally{control.disabled=false;control.textContent='Fetch details';}return;}if(action==='recommend'){if(!currentUser){signIn('#/community');return;}control.disabled=true;try{const data=await api(`/api/submissions/${control.dataset.id}/recommend`,{method:'POST'});communitySubmissions=communitySubmissions.map(item=>item.id===data.submission.id?data.submission:item);render(false);}catch(error){toast(error.message);}return;}if(action==='vote-wanted'){if(!currentUser){signIn('#/wanted');return;}control.disabled=true;try{const data=await api(`/api/wanted/${control.dataset.id}/vote`,{method:'POST'});wantedRequests=wantedRequests.map(item=>item.id===data.request.id?data.request:item);wantedRequests.sort((a,b)=>(b.status==='open')-(a.status==='open')||b.voteCount-a.voteCount);render(false);}catch(error){toast(error.message);}return;}if(action==='open-filters'){openFilters();return;}if(action==='toggle-selfhost'){updateFilter('selfHosted',readFilters(parseRoute().params).selfHosted?null:'1');return;}if(action==='load-more'){visibleLimit+=24;render(false);main.querySelectorAll('.catalog-card')[visibleLimit-24]?.querySelector('a')?.focus({preventScroll:true});}if(action==='reset-filters'){const r=parseRoute();history.pushState(null,'',r.path==='/trending'?'#/trending':r.path==='/new'?'#/new':'#/browse');render(false);}if(action==='clear-search'){updateFilter('q','',{replace:true});document.querySelector('#app-search')?.focus();}const image=e.target.closest('[data-image]');if(image){const dialog=document.querySelector('#image-dialog');dialog.querySelector('img').src='assets/'+image.dataset.image;dialog.querySelector('img').alt=image.dataset.caption;dialog.querySelector('p').textContent=image.dataset.caption;dialog.showModal();}const save=e.target.closest('[data-save]');if(save){const id=save.dataset.save;if(saved.has(id))saved.delete(id);else saved.add(id);try{localStorage.setItem('openstore-saved',JSON.stringify([...saved]));}catch{}save.setAttribute('aria-pressed',saved.has(id));save.setAttribute('aria-label',`${saved.has(id)?'Unsave':'Save'} ${projects.find(p=>p.id===id).name}`);toast(saved.has(id)?'Saved to this browser.':'Removed from saved apps.');}});
main.addEventListener('submit',async e=>{const form=e.target;if(!form.matches('#submission-form,#wanted-form,.solution-form,.moderation-form,.feedback-form'))return;e.preventDefault();const submitter=e.submitter,feedback=form.querySelector('.form-feedback'),button=submitter||form.querySelector('[type="submit"]');feedback.textContent='';button.disabled=true;const original=button.innerHTML;button.textContent='Saving…';try{const data=new FormData(form);if(form.classList.contains('feedback-form')){const result=await api(`/api/submissions/${form.dataset.id}/feedback`,{method:'POST',body:JSON.stringify({note:data.get('note')})});communitySubmissions=communitySubmissions.map(item=>item.id===result.submission.id?result.submission:item);render(false);toast('Feedback sent to editors.');return;}if(form.id==='submission-form'){const payload={repoUrl:data.get('repoUrl'),company:data.get('company'),name:data.get('name'),description:data.get('description'),websiteUrl:data.get('websiteUrl'),docsUrl:data.get('docsUrl'),category:data.get('category'),alternatives:data.get('alternatives'),platforms:data.getAll('platforms'),selfHosted:data.has('selfHosted'),bestFor:data.get('bestFor'),consideration:data.get('consideration')};await api('/api/submissions',{method:'POST',body:JSON.stringify(payload)});await refreshCommunity();toast('Submitted for editorial review.');location.hash='/community';return;}if(form.id==='wanted-form'){await api('/api/wanted',{method:'POST',body:JSON.stringify({productName:data.get('productName'),description:data.get('description')})});await refreshWanted();toast('Alternative request added.');location.hash='/wanted';return;}if(form.classList.contains('solution-form')){const catalogId=data.get('catalogId'),githubUrl=data.get('githubUrl');if(!catalogId&&!githubUrl)throw new Error('Choose an OpenStore app or enter a GitHub repository.');await api(`/api/wanted/${form.dataset.requestId}/solutions`,{method:'POST',body:JSON.stringify({catalogId,githubUrl})});await refreshWanted();toast('Solution suggested.');return;}if(form.classList.contains('moderation-form')){const payload=submitter.value==='rejected'?{status:'rejected',moderatorNote:data.get('moderatorNote')}:{status:submitter.value,name:data.get('name'),description:data.get('description'),websiteUrl:data.get('websiteUrl'),category:data.get('category'),alternatives:data.get('alternatives'),platforms:data.get('platforms'),selfHosted:data.has('selfHosted'),bestFor:data.get('bestFor'),consideration:data.get('consideration'),moderatorNote:data.get('moderatorNote')};await api(`/api/admin/submissions/${form.dataset.id}`,{method:'PATCH',body:JSON.stringify(payload)});adminQueue=null;await Promise.all([refreshCommunity(),loadAdmin()]);toast(original.includes('Save edits')?'Edits saved.':payload.status==='approved'?'Accepted for later curation.':'Submission rejected.');return;}}catch(error){if(error.code==='auth_required'){signIn(location.hash);return;}feedback.textContent=error.message;}finally{button.disabled=false;button.innerHTML=original;}});
main.addEventListener('submit',async e=>{const form=e.target;if(!form.matches('.wanted-resolution-form'))return;e.preventDefault();const button=e.submitter,feedback=form.querySelector('.form-feedback'),data=new FormData(form);feedback.textContent='';button.disabled=true;try{await api(`/api/admin/wanted/${form.dataset.id}`,{method:'PATCH',body:JSON.stringify({solutionId:data.get('solutionId')})});await refreshWanted();render(false);toast('Wanted request resolved.');}catch(error){feedback.textContent=error.message;}finally{button.disabled=false;}});
main.addEventListener('click',e=>{if(e.target.closest('[data-action="reload-admin"]')){adminQueue=null;loadAdmin();render(false);}});
main.addEventListener('input',e=>{const counter=e.target.name&&e.target.form?.querySelector(`[data-count="${e.target.name}"]`);if(counter)counter.textContent=`${e.target.value.length} / ${e.target.maxLength}`;});
main.addEventListener('change',e=>{if(e.target.id==='submit-repo-url'&&/^https?:\/\/(www\.)?github\.com\/[^/\s]+\/[^/\s]+/i.test(e.target.value.trim()))e.target.form.querySelector('[data-action="fetch-metadata"]').click();});
window.addEventListener('hashchange',()=>render());
window.addEventListener('popstate',()=>render());
function focusSearch(){if(!document.querySelector('#app-search')){history.pushState(null,'','#/browse');render();}document.querySelector('#app-search')?.focus();}
document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView();});
document.querySelector('#search-shortcut').innerHTML=svg('search');document.querySelector('#search-shortcut').addEventListener('click',focusSearch);
document.querySelector('#github-nav').insertAdjacentHTML('afterbegin',svg('github'));
const themeToggle=document.querySelector('#theme-toggle');
function updateThemeControl(){const dark=document.documentElement.dataset.theme==='dark';const label=`Switch to ${dark?'light':'dark'} mode`;themeToggle.innerHTML=svg(dark?'sun':'moon');themeToggle.setAttribute('aria-label',label);themeToggle.title=label;document.querySelector('meta[name="theme-color"]').content=dark?'#101113':'#ffffff';}
themeToggle.addEventListener('click',()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('openstore-theme',theme);}catch{}updateThemeControl();});
updateThemeControl();
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();focusSearch();}if(e.key==='Escape'&&document.activeElement?.id==='app-search'){document.activeElement.blur();}});
document.querySelector('#about-button').addEventListener('click',()=>document.querySelector('#about-dialog').showModal());
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close();}});});
document.querySelector('#filter-form').addEventListener('submit',e=>{e.preventDefault();const dialog=document.querySelector('#filter-dialog'),data=new FormData(e.target),route=parseRoute();for(const key of ['stars','selfHosted','trending','openOnly','reviewed']){if(key==='trending'&&route.path==='/trending')continue;const value=data.get(key);if(value&&value!=='0')route.params.set(key,key==='stars'?value:'1');else route.params.delete(key);}dialog.close();history.pushState(null,'',`#${route.path}${route.params.size?'?'+route.params.toString():''}`);render(false);main.querySelector('[data-action="open-filters"]')?.focus({preventScroll:true});});
document.querySelector('#clear-advanced-filters').addEventListener('click',()=>{document.querySelector('#filter-form').reset();document.querySelector('#filter-form select').value='0';document.querySelectorAll('#filter-form input').forEach(input=>input.checked=false);});
async function loadJSON(path){const response=await fetch(path);if(!response.ok)throw new Error(`Unable to load ${path}`);return response.json();}
try {
 const loaded=await Promise.allSettled([loadJSON('assets/github-snapshot.json'),loadJSON('assets/trending-snapshot.json'),loadJSON('assets/asset-sources.json'),loadJSON('assets/official-icons.json'),loadJSON('assets/reviews-snapshot.json'),api('/api/auth/me'),api('/api/community'),api('/api/wanted'),api('/api/catalog-choices')]);
 snapshot=loaded[0].status==='fulfilled'?loaded[0].value:{};trendSnapshot=loaded[1].status==='fulfilled'?loaded[1].value:{};assetSources=loaded[2].status==='fulfilled'?loaded[2].value:{};officialIcons=loaded[3].status==='fulfilled'?loaded[3].value:{};reviewSnapshot=loaded[4].status==='fulfilled'?loaded[4].value:{};
 if(projects.some(p=>!officialIcons[p.id]?.file))throw new Error('Official project icons are unavailable.');
 projects=projects.map(p=>{const stats=snapshot.repositories?.[p.repo];const trend=trendSnapshot.repositories?.find(t=>t.repo.toLowerCase()===p.repo.toLowerCase());return {...p,review:reviewSnapshot.projects?.[p.id],bestFor:p.bestFor||reviewSnapshot.projects?.[p.id]?.useCase,stars:stats?.stargazers_count,forks:stats?.forks_count,updatedAt:stats?.pushed_at,createdAt:stats?.created_at,trending:!!trend,weeklyStars:trend?.weeklyStars,screens:p.screens.filter(([file])=>assetSources[file]&&!assetSources[file].error)};});
 currentUser=loaded[5].status==='fulfilled'?loaded[5].value.user:null;
 if(loaded[6].status==='fulfilled'){communitySubmissions=loaded[6].value.submissions;}else communityError='The community service is unavailable.';
 if(loaded[7].status==='fulfilled')wantedRequests=loaded[7].value.requests;else wantedError='The request board is unavailable.';
 if(loaded[8].status==='fulfilled')catalogChoiceList=loaded[8].value.apps;
 document.querySelector('#snapshot-info').textContent=`Repository metadata: ${date(snapshot.fetchedAt)}. Curated source listings use verified official project icons. Screenshots are sourced from official repositories and websites.`;
 render();
} catch(error){main.innerHTML=`<div class="empty-state"><h2>Let’s try that again.</h2><p>The collection couldn’t load. Refresh to try again.</p><button class="button button-primary" onclick="location.reload()">Refresh OpenStore</button></div>`;console.error(error);}
